from contextlib import contextmanager

@contextmanager
def step(name):
    print(f"[{name}] начали")
    try:
        yield name                    # сюда попадёт то, что после as
    finally:
        print(f"[{name}] закончили")   # выполнится даже при исключении

with step("загрузка") as s:
    print(f"  работаем внутри {s}")

print()

# своё исключение: ловится точно, а не заодно с чужими
class NotEnoughMoney(Exception):
    def __init__(self, need, have):
        super().__init__(f"нужно {need}, а есть {have}")
        self.need = need
        self.have = have

def withdraw(balance, amount):
    if amount > balance:
        raise NotEnoughMoney(amount, balance)
    return balance - amount

print("снимаем 30:", withdraw(100, 30))

try:
    withdraw(100, 500)
except NotEnoughMoney as e:
    print("поймали своё:", e)
    print("не хватает:", e.need - e.have)

print()

# finally срабатывает даже когда внутри всё сломалось
try:
    with step("опасный шаг"):
        raise ValueError("что-то пошло не так")
except ValueError as e:
    print("снаружи поймали:", e)

