tasks.tests:
assert issubclass(NotEnoughMoney, Exception), 'NotEnoughMoney должен наследовать Exception'
assert withdraw(100, 30) == 70, 'Обычное снятие'
assert withdraw(50, 50) == 0, 'Можно снять всё'
try:
    withdraw(100, 500)
    assert False, 'Должно было выбросить NotEnoughMoney'
except NotEnoughMoney as e:
    assert e.need == 500, 'Поле need'
    assert e.have == 100, 'Поле have'
try:
    withdraw(100, 0)
    assert False, 'Нулевая сумма — это ValueError'
except ValueError:
    pass
try:
    withdraw(100, -5)
    assert False, 'Отрицательная сумма — это ValueError'
except ValueError:
    pass

